import { MakeLogicType, afterMount, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { ApiConfig } from 'lib/api'

import { isSharedView } from '~/exporter/exporterViewLogic'

import { insightVariablesList, insightVariablesDestroy } from 'products/data_warehouse/frontend/generated/api'

import { Variable } from '../../types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface variableDataLogicValues {
    variables: Variable[]
    variablesLoaded: boolean
    variablesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface variableDataLogicActions {
    deleteVariable: (variableId: string) => string
    deleteVariableFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    deleteVariableSuccess: (
        variables: Variable[],
        payload?: string
    ) => {
        variables: Variable[]
        payload?: string
    }
    loadVariables: () => any
    loadVariablesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadVariablesSuccess: (
        variables: Variable[],
        payload?: any
    ) => {
        variables: Variable[]
        payload?: any
    }
}

export type variableDataLogicType = MakeLogicType<variableDataLogicValues, variableDataLogicActions>

export const variableDataLogic = kea<variableDataLogicType>([
    path(['queries', 'nodes', 'DataVisualization', 'Components', 'Variables', 'variableDataLogic']),
    loaders(({ values }) => ({
        variables: [
            [] as Variable[],
            {
                loadVariables: async () => {
                    if (isSharedView()) {
                        return []
                    }
                    const variables: Variable[] = []
                    const teamId = String(ApiConfig.getCurrentTeamId())
                    let page = 1
                    while (true) {
                        const response = await insightVariablesList(teamId, { page })
                        variables.push(...(response.results as Variable[]))
                        if (!response.next) {
                            return variables
                        }
                        page++
                    }
                },
                deleteVariable: async (variableId: string) => {
                    try {
                        await insightVariablesDestroy(String(ApiConfig.getCurrentTeamId()), variableId)
                        lemonToast.success('Variable deleted successfully')
                    } catch {
                        lemonToast.error('Failed to delete variable')
                        return values.variables
                    }
                    return values.variables.filter((variable) => variable.id !== variableId)
                },
            },
        ],
    })),
    reducers({
        variablesLoaded: [false, { loadVariablesSuccess: () => true }],
    }),
    afterMount(({ actions }) => {
        actions.loadVariables()
    }),
])
